import java.io.*
import java.util.*

class F {
    private var n = 0
    private var m = 0
    private var arr: IntArray = intArrayOf()
    private var required = 0
    private var typeDays: HashMap<Int, TreeSet<Int>> = HashMap()

    fun solver() {
        n = FastScanner.intNext()
        m = FastScanner.intNext()
        arr = FastScanner.nextIntArray(n)
        required = arr.sum()
        typeDays = HashMap()
        for (i in 0 until m) {
            val d = FastScanner.intNext()
            val typ = FastScanner.intNext()
            if (arr[typ - 1] <= 0) continue
            typeDays.computeIfAbsent(typ) { TreeSet() }.add(d)
        }

        var lo = required
        var hi = 2 * required
        var valid = hi
        while (lo <= hi) {
            val mid = (lo + hi) / 2
            if (isEnough(mid)) {
                valid = mid
                hi = mid - 1
            } else {
                lo = mid + 1
            }
        }
        FastWriter.println(valid)
    }

    private fun isEnough(day: Int): Boolean {
        var totalCoin = day
        var req = required

        val ddays = IntArray(day + 1)
        for (typ in typeDays.keys) {
            val lastDay = typeDays[typ]?.floor(day)
            if (lastDay == null) continue
            ddays[lastDay] += arr[typ - 1]
        }

        var removed = 0
        for (i in 1..day) {
            val coins = i - removed
            val toRemove = minOf(coins, ddays[i])
            removed += toRemove
            totalCoin -= toRemove
            req -= toRemove
        }
        return req * 2 <= totalCoin
    }
}

object FastWriter {
    private const val IO_BUFFERS = 128 * 1024
    private val out = StringBuilder(IO_BUFFERS)

    fun p(object: Any?): FastWriter.type { out.append(object); return this }
    fun p(format: String, vararg args: Any?): FastWriter.type { out.append(String.format(format, *args)); return this }
    fun pp(vararg args: Any?): FastWriter.type { for (ob in args) out.append(ob).append(" "); out.append("\n"); return this }
    fun pp(args: IntArray): FastWriter.type { for (ob in args) out.append(ob).append(" "); out.append("\n"); return this }
    fun pp(args: LongArray): FastWriter.type { for (ob in args) out.append(ob).append(" "); out.append("\n"); return this }
    fun pp(args: CharArray): FastWriter.type { for (ob in args) out.append(ob).append(" "); out.append("\n"); return this }
    fun println(arr: LongArray) { for (e in arr) out.append(e).append(" "); out.append("\n") }
    fun println(arr: IntArray) { for (e in arr) out.append(e).append(" "); out.append("\n") }
    fun println(arr: CharArray) { for (e in arr) out.append(e).append(" "); out.append("\n") }
    fun println(arr: DoubleArray) { for (e in arr) out.append(e).append(" "); out.append("\n") }
    fun println(arr: BooleanArray) { for (e in arr) out.append(e).append(" "); out.append("\n") }
    fun <T> println(arr: Array<T>) { for (e in arr) out.append(e).append(" "); out.append("\n") }
    fun println(arr: Array<LongArray>) { for (row in arr) out.append(row.contentToString()).append("\n") }
    fun println(arr: Array<IntArray>) { for (row in arr) out.append(row.contentToString()).append("\n") }
