    fun <T> println(arr: Array<Array<T>>) { for (row in arr) out.append(row.contentToString()).append("\n") }
    fun println(object: Any?): FastWriter.type { out.append(object).append("\n"); return this }

    fun toFile(fileName: String) {
        BufferedWriter(FileWriter(fileName)).use { it.write(out.toString()) }
