    fun customSort(arr: Array<IntArray>) {
        Arrays.sort(arr) { a, b ->
            if (a[0] == b[0]) Integer.compare(a[1], b[1]) else Integer.compare(a[0], b[0])
        }
    }

    fun swap(arr: IntArray, left: Int, right: Int): IntArray { val t = arr[left]; arr[left] = arr[right]; arr[right] = t; return arr }
    fun swap(arr: CharArray, left: Int, right: Int): CharArray { val t = arr[left]; arr[left] = arr[right]; arr[right] = t; return arr }
    fun reverse(arr: IntArray, left: Int, right: Int): IntArray {
        var l = left; var r = right
        while (l < r) { val t = arr[l]; arr[l] = arr[r]; arr[r] = t; l++; r-- }
        return arr
    }

    fun findNextPermutation(data: IntArray): Boolean {
        if (data.size <= 1) return false
        var last = data.size - 2
        while (last >= 0 && data[last] >= data[last + 1]) last--
        if (last < 0) return false
        var nextGreater = data.size - 1
        for (i in data.size - 1 downTo last + 1) if (data[i] > data[last]) { nextGreater = i; break }
        swap(data, nextGreater, last)
        reverse(data, last + 1, data.size - 1)
        return true
    }

    fun biSearch(dt: IntArray, target: Int): Int {
        var left = 0; var right = dt.lastIndex
        while (left <= right) {
            val mid = (left + right) / 2
            when {
                dt[mid] == target -> return mid
                dt[mid] < target -> left = mid + 1
                else -> right = mid - 1
            }
        }
        return -1
    }

    fun biSearchMax(dt: LongArray, target: Long): Int {
        var left = -1; var right = dt.size
        while (right - left > 1) {
            val mid = left + (right - left) / 2
            if (dt[mid] <= target) left = mid else right = mid
        }
        return left
    }

