import java.io.*
import java.util.*

class FastScanner(private val `in`: InputStream = System.`in`) {
    private val buffer = ByteArray(1024)
    private var ptr = 0
    private var buflen = 0

    private fun hasNextByte(): Boolean {
        if (ptr < buflen) return true
        ptr = 0
        try {
            buflen = `in`.read(buffer)
        } catch (e: IOException) {
            e.printStackTrace()
        }
        return buflen > 0
    }

    private fun readByte(): Int {
        if (hasNextByte()) return buffer[ptr++].toInt()
        return -1
    }

    companion object {
        private fun isPrintableChar(c: Int): Boolean = c in 33..126
    }

    fun hasNext(): Boolean {
        while (hasNextByte() && !isPrintableChar(buffer[ptr])) ptr++
        return hasNextByte()
    }

    fun next(): String {
        if (!hasNext()) throw NoSuchElementException()
        val sb = StringBuilder()
        var b = readByte()
        while (isPrintableChar(b)) {
            sb.appendCodePoint(b)
            b = readByte()
        }
        return sb.toString()
    }

    fun longNext(): Long {
        if (!hasNext()) throw NoSuchElementException()
        var n = 0L
        var minus = false
        var b = readByte()
        if (b == '-'.toInt()) {
            minus = true
            b = readByte()
        }
        if (b !in '0'..'9') throw NumberFormatException()
        while (true) {
            if (b in '0'..'9') {
                n = n * 10 + (b - '0'.toInt())
            } else if (b == -1 || !isPrintableChar(b) || b == ':'.toInt()) {
                return if (minus) -n else n
            } else {
                throw NumberFormatException()
            }
            b = readByte()
        }
    }

    fun intNext(): Int {
        val nl = longNext()
        if (nl < Int.MIN_VALUE || nl > Int.MAX_VALUE) throw NumberFormatException()
        return nl.toInt()
    }

    fun doubleNext(): Double = next().toDouble()

    fun nextLongArray(n: Int): LongArray {
        val a = LongArray(n)
        for (i in 0 until n) a[i] = longNext()
        return a
    }

    fun nextIntArray(n: Int): IntArray {
        val a = IntArray(n)
        for (i in 0 until n) a[i] = intNext()
        return a
    }

    fun nextDoubleArray(n: Int): DoubleArray {
        val a = DoubleArray(n)
        for (i in 0 until n) a[i] = doubleNext()
        return a
    }

    fun getAdj(n: Int): Array<ArrayList<Int>> {
        val adj = Array(n + 1) { ArrayList<Int>() }
        return adj
    }

    fun adjacencyList(nodes: Int, edges: Int, isDirected: Boolean = false): Array<ArrayList<Int>> {
        val adj = getAdj(nodes)
        for (i in 0 until edges) {
            val a = intNext()
            val b = intNext()
            adj[a].add(b)
            if (!isDirected) adj[b].add(a)
        }
        return adj
    }
}

