class Tuple(var a: Int, var b: Int, var c: Int = 0) : Comparable<Tuple> {
    override fun compareTo(other: Tuple): Int {
        if (a != other.a) return a.compareTo(other.a)
        if (b != other.b) return b.compareTo(other.b)
        return c.compareTo(other.c)
    }
    override fun hashCode(): Int = Arrays.deepHashCode(arrayOf(a, b, c))
    override fun equals(other: Any?): Boolean {
        if (other !is Tuple) return false
        return a == other.a && b == other.b && c == other.c
    }
    override fun toString() = "($a $b $c)  "
}

