class F {
    var n = 0
    var m = 0
    var arr: IntArray = IntArray(0)
    var required = 0
    val typeDays = mutableMapOf<Int, TreeSet<Int>>()

    fun solver() {
        n = `in`.intNext()
        m = `in`.intNext()
        arr = `in`.nextIntArray(n)
        required = arr.sum()
        typeDays.clear()
        repeat(m) {
            val d = `in`.intNext()
            val typ = `in`.intNext()
            if (arr[typ - 1] <= 0) continue
            typeDays.getOrPut(typ) { TreeSet() }.add(d)
        }

        var lo = required
        var hi = 2 * required
        var valid = hi
        while (lo <= hi) {
            val mid = (lo + hi) / 2
            if (isEnough(mid)) {
                valid = mid
                hi = mid - 1
            } else {
                lo = mid + 1
            }
        }
        out.println(valid)
    }

